import { Chart, registerables } from "chart.js";

Chart.register(...registerables);

// ─── Types ──────────────────────────────────────────────────────────────────
export interface ChartBlockData {
  chartType: "bar" | "line" | "pie" | "doughnut" | "radar" | "polarArea";
  title: string;
  labels: string[];
  datasets: Array<{
    label: string;
    data: number[];
    backgroundColor: string;
    borderColor: string;
  }>;
}

interface ChartBlockConstructorOptions {
  data: Partial<ChartBlockData>;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  api: any;
  readOnly: boolean;
}

// ─── Constants ──────────────────────────────────────────────────────────────
const CHART_TYPES: Array<{
  value: ChartBlockData["chartType"];
  label: string;
  icon: string;
}> = [
  {
    value: "bar",
    label: "Bar",
    icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="12" width="4" height="9" rx="1"/><rect x="10" y="7" width="4" height="14" rx="1"/><rect x="17" y="3" width="4" height="18" rx="1"/></svg>',
  },
  {
    value: "line",
    label: "Line",
    icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="3 17 9 11 13 15 21 7"/><polyline points="17 7 21 7 21 11"/></svg>',
  },
  {
    value: "pie",
    label: "Pie",
    icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 12a9 9 0 1 1-9-9"/><path d="M21 12H12V3a9 9 0 0 1 9 9z"/></svg>',
  },
  {
    value: "doughnut",
    label: "Doughnut",
    icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><circle cx="12" cy="12" r="4"/><path d="M12 3v4"/></svg>',
  },
  {
    value: "radar",
    label: "Radar",
    icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polygon points="12 2 22 8.5 22 15.5 12 22 2 15.5 2 8.5"/><polygon points="12 6 18 9.5 18 14.5 12 18 6 14.5 6 9.5"/></svg>',
  },
  {
    value: "polarArea",
    label: "Polar",
    icon: '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><line x1="12" y1="3" x2="12" y2="21"/><line x1="3" y1="12" x2="21" y2="12"/></svg>',
  },
];

const COLOR_PALETTE = [
  { bg: "rgba(54, 162, 235, 0.5)", border: "rgb(54, 162, 235)" },
  { bg: "rgba(255, 99, 132, 0.5)", border: "rgb(255, 99, 132)" },
  { bg: "rgba(75, 192, 192, 0.5)", border: "rgb(75, 192, 192)" },
  { bg: "rgba(255, 205, 86, 0.5)", border: "rgb(255, 205, 86)" },
  { bg: "rgba(153, 102, 255, 0.5)", border: "rgb(153, 102, 255)" },
  { bg: "rgba(255, 159, 64, 0.5)", border: "rgb(255, 159, 64)" },
  { bg: "rgba(201, 203, 207, 0.5)", border: "rgb(201, 203, 207)" },
  { bg: "rgba(46, 204, 113, 0.5)", border: "rgb(46, 204, 113)" },
];

const DEFAULT_DATA: ChartBlockData = {
  chartType: "bar",
  title: "",
  labels: ["Label 1", "Label 2", "Label 3"],
  datasets: [
    {
      label: "Dataset 1",
      data: [10, 20, 30],
      backgroundColor: COLOR_PALETTE[0].bg,
      borderColor: COLOR_PALETTE[0].border,
    },
  ],
};

const TOOLBOX_ICON =
  '<svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><rect x="3" y="12" width="4" height="9" rx="1"/><rect x="10" y="7" width="4" height="14" rx="1"/><rect x="17" y="3" width="4" height="18" rx="1"/></svg>';

// ─── ChartBlockTool ─────────────────────────────────────────────────────────
export default class ChartBlockTool {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private api: any;
  private readOnly: boolean;
  private data: ChartBlockData;
  private chart: Chart | null = null;
  private wrapper: HTMLDivElement | null = null;
  private canvas: HTMLCanvasElement | null = null;
  private tableWrapper: HTMLDivElement | null = null;
  private editorPanel: HTMLDivElement | null = null;
  private updateTimeout: number | null = null;
  private boundOnClickOutside: ((e: MouseEvent) => void) | null = null;

  static get isReadOnlySupported(): boolean {
    return true;
  }

  static get toolbox(): { title: string; icon: string } {
    return { title: "Chart", icon: TOOLBOX_ICON };
  }

  constructor({ data, api, readOnly }: ChartBlockConstructorOptions) {
    this.api = api;
    this.readOnly = readOnly;
    this.data = this.normalizeData(data);
  }

  // ─── Lifecycle ──────────────────────────────────────────────────────────────

  render(): HTMLElement {
    this.wrapper = document.createElement("div");
    this.wrapper.classList.add("cdx-chart-block");

    if (this.readOnly) {
      this.buildReadOnlyUI();
    } else {
      this.buildEditUI();

      // Start collapsed — show only the chart
      if (this.editorPanel) {
        this.editorPanel.classList.add("cdx-chart-block__editor-panel--hidden");
      }

      // Click on the block → expand editing panel
      this.wrapper.addEventListener("click", () => {
        if (
          this.editorPanel &&
          this.editorPanel.classList.contains("cdx-chart-block__editor-panel--hidden")
        ) {
          this.editorPanel.classList.remove("cdx-chart-block__editor-panel--hidden");
          // Re-create chart since canvas may have been resized
          this.createChart();
        }
      });

      // Click outside → collapse
      this.boundOnClickOutside = (e: MouseEvent) => {
        if (this.wrapper && this.editorPanel && !this.wrapper.contains(e.target as Node)) {
          this.editorPanel.classList.add("cdx-chart-block__editor-panel--hidden");
          // Re-create chart to fit new size
          this.createChart();
        }
      };
      document.addEventListener("click", this.boundOnClickOutside);
    }

    // Defer chart creation until DOM is mounted
    requestAnimationFrame(() => this.createChart());

    return this.wrapper;
  }

  save(): ChartBlockData {
    return {
      chartType: this.data.chartType,
      title: this.data.title,
      labels: [...this.data.labels],
      datasets: this.data.datasets.map((ds) => ({
        label: ds.label,
        data: [...ds.data],
        backgroundColor: ds.backgroundColor,
        borderColor: ds.borderColor,
      })),
    };
  }

  validate(savedData: ChartBlockData): boolean {
    return (
      Array.isArray(savedData.labels) &&
      savedData.labels.length > 0 &&
      Array.isArray(savedData.datasets) &&
      savedData.datasets.length > 0
    );
  }

  destroy(): void {
    if (this.updateTimeout !== null) {
      clearTimeout(this.updateTimeout);
      this.updateTimeout = null;
    }
    if (this.chart) {
      this.chart.destroy();
      this.chart = null;
    }
    if (this.boundOnClickOutside) {
      document.removeEventListener("click", this.boundOnClickOutside);
      this.boundOnClickOutside = null;
    }
  }

  renderSettings() {
    return CHART_TYPES.map((type) => ({
      icon: type.icon,
      label: type.label,
      isActive: this.data.chartType === type.value,
      closeOnActivate: true,
      onActivate: () => {
        this.data.chartType = type.value;
        this.updateTypeSelector();
        this.createChart();
      },
    }));
  }

  // ─── UI Builders ────────────────────────────────────────────────────────────

  private buildReadOnlyUI(): void {
    if (!this.wrapper) return;

    if (this.data.title) {
      const title = document.createElement("div");
      title.className = "cdx-chart-block__title";
      title.textContent = this.data.title;
      this.wrapper.appendChild(title);
    }

    this.appendCanvas();
  }

  private buildEditUI(): void {
    if (!this.wrapper) return;

    // Editor panel — all editing controls wrapped in a collapsible container
    this.editorPanel = document.createElement("div");
    this.editorPanel.className = "cdx-chart-block__editor-panel";

    // Title input
    const titleInput = document.createElement("input");
    titleInput.type = "text";
    titleInput.className = "cdx-chart-block__title-input";
    titleInput.placeholder = "Chart title (optional)";
    titleInput.value = this.data.title;
    titleInput.addEventListener("input", () => {
      this.data.title = titleInput.value;
      this.scheduleChartUpdate();
    });
    this.editorPanel.appendChild(titleInput);

    // Chart type selector
    const typeSelector = document.createElement("div");
    typeSelector.className = "cdx-chart-block__type-selector";

    CHART_TYPES.forEach((type) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "cdx-chart-block__type-btn";
      btn.dataset.chartType = type.value;
      if (this.data.chartType === type.value) {
        btn.classList.add("cdx-chart-block__type-btn--active");
      }
      btn.innerHTML = `${type.icon} ${type.label}`;
      btn.addEventListener("click", () => {
        this.data.chartType = type.value;
        this.updateTypeSelector();
        this.createChart();
      });
      typeSelector.appendChild(btn);
    });

    this.editorPanel.appendChild(typeSelector);

    // Data table
    this.tableWrapper = document.createElement("div");
    this.tableWrapper.className = "cdx-chart-block__table-wrapper";
    this.editorPanel.appendChild(this.tableWrapper);
    this.rebuildDataTable();

    // Action buttons
    const actions = document.createElement("div");
    actions.className = "cdx-chart-block__actions";

    const addLabelBtn = document.createElement("button");
    addLabelBtn.type = "button";
    addLabelBtn.className = "cdx-chart-block__action-btn";
    addLabelBtn.textContent = "+ Add Label";
    addLabelBtn.addEventListener("click", () => this.addLabel());

    const addDatasetBtn = document.createElement("button");
    addDatasetBtn.type = "button";
    addDatasetBtn.className = "cdx-chart-block__action-btn";
    addDatasetBtn.textContent = "+ Add Dataset";
    addDatasetBtn.addEventListener("click", () => this.addDataset());

    actions.appendChild(addLabelBtn);
    actions.appendChild(addDatasetBtn);
    this.editorPanel.appendChild(actions);

    this.wrapper.appendChild(this.editorPanel);

    // Canvas — always visible, outside the editor panel
    this.appendCanvas();
  }

  private appendCanvas(): void {
    if (!this.wrapper) return;

    const canvasWrapper = document.createElement("div");
    canvasWrapper.className = "cdx-chart-block__canvas-wrapper";

    this.canvas = document.createElement("canvas");
    canvasWrapper.appendChild(this.canvas);
    this.wrapper.appendChild(canvasWrapper);
  }

  // ─── Data Table ─────────────────────────────────────────────────────────────

  private rebuildDataTable(): void {
    if (!this.tableWrapper) return;
    this.tableWrapper.innerHTML = "";

    const table = document.createElement("table");
    table.className = "cdx-chart-block__table";

    // Header row: corner + label inputs + empty controls column
    const thead = document.createElement("thead");
    const headerRow = document.createElement("tr");

    // Corner cell
    const corner = document.createElement("th");
    corner.className = "cdx-chart-block__corner-cell";
    headerRow.appendChild(corner);

    // Label cells
    this.data.labels.forEach((label, colIdx) => {
      const th = document.createElement("th");
      th.className = "cdx-chart-block__label-cell";

      const labelInput = document.createElement("input");
      labelInput.type = "text";
      labelInput.className = "cdx-chart-block__label-input";
      labelInput.value = label;
      labelInput.addEventListener("input", () => {
        this.data.labels[colIdx] = labelInput.value;
        this.scheduleChartUpdate();
      });
      th.appendChild(labelInput);

      if (this.data.labels.length > 1) {
        const removeBtn = document.createElement("button");
        removeBtn.type = "button";
        removeBtn.className = "cdx-chart-block__remove-col-btn";
        removeBtn.innerHTML = "&times;";
        removeBtn.title = "Remove label";
        removeBtn.addEventListener("click", () => this.removeLabel(colIdx));
        th.appendChild(removeBtn);
      }

      headerRow.appendChild(th);
    });

    // Controls column header (empty)
    const controlsHeader = document.createElement("th");
    controlsHeader.className = "cdx-chart-block__controls-header";
    headerRow.appendChild(controlsHeader);

    thead.appendChild(headerRow);
    table.appendChild(thead);

    // Body rows: one per dataset
    const tbody = document.createElement("tbody");

    this.data.datasets.forEach((dataset, rowIdx) => {
      const tr = document.createElement("tr");
      tr.className = "cdx-chart-block__dataset-row";

      // Dataset name cell
      const nameCell = document.createElement("td");
      nameCell.className = "cdx-chart-block__dataset-name-cell";
      const nameInput = document.createElement("input");
      nameInput.type = "text";
      nameInput.className = "cdx-chart-block__dataset-name";
      nameInput.value = dataset.label;
      nameInput.placeholder = "Dataset name";
      nameInput.addEventListener("input", () => {
        this.data.datasets[rowIdx].label = nameInput.value;
        this.scheduleChartUpdate();
      });
      nameCell.appendChild(nameInput);
      tr.appendChild(nameCell);

      // Data value cells
      this.data.labels.forEach((_, colIdx) => {
        const td = document.createElement("td");
        const dataInput = document.createElement("input");
        dataInput.type = "number";
        dataInput.className = "cdx-chart-block__data-input";
        dataInput.value = String(dataset.data[colIdx] ?? 0);
        dataInput.addEventListener("input", () => {
          this.data.datasets[rowIdx].data[colIdx] = parseFloat(dataInput.value) || 0;
          this.scheduleChartUpdate();
        });
        td.appendChild(dataInput);
        tr.appendChild(td);
      });

      // Controls cell: color picker + remove button
      const controlsCell = document.createElement("td");
      controlsCell.className = "cdx-chart-block__dataset-controls";

      const colorPicker = document.createElement("input");
      colorPicker.type = "color";
      colorPicker.className = "cdx-chart-block__color-picker";
      colorPicker.value = this.rgbaToHex(dataset.backgroundColor);
      colorPicker.title = "Dataset color";
      colorPicker.addEventListener("input", () => {
        this.data.datasets[rowIdx].backgroundColor = this.hexToRgba(colorPicker.value, 0.5);
        this.data.datasets[rowIdx].borderColor = this.hexToRgba(colorPicker.value, 1);
        this.scheduleChartUpdate();
      });
      controlsCell.appendChild(colorPicker);

      if (this.data.datasets.length > 1) {
        const removeBtn = document.createElement("button");
        removeBtn.type = "button";
        removeBtn.className = "cdx-chart-block__remove-btn";
        removeBtn.innerHTML = "&times;";
        removeBtn.title = "Remove dataset";
        removeBtn.addEventListener("click", () => this.removeDataset(rowIdx));
        controlsCell.appendChild(removeBtn);
      }

      tr.appendChild(controlsCell);
      tbody.appendChild(tr);
    });

    table.appendChild(tbody);
    this.tableWrapper.appendChild(table);
  }

  // ─── Chart ──────────────────────────────────────────────────────────────────

  private createChart(): void {
    if (!this.canvas) return;

    if (this.chart) {
      this.chart.destroy();
      this.chart = null;
    }

    const dark = this.isDarkMode();
    const textColor = dark ? "#e0e0e0" : "#333";
    const gridColor = dark ? "rgba(255, 255, 255, 0.1)" : "rgba(0, 0, 0, 0.1)";
    const legendColor = dark ? "#ccc" : "#666";

    const isPieType = ["pie", "doughnut", "polarArea"].includes(this.data.chartType);

    // For pie/doughnut/polar, use per-segment colors from all datasets flattened
    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const datasets: any[] = this.data.datasets.map((ds) => {
      if (isPieType) {
        return {
          label: ds.label,
          data: [...ds.data],
          borderWidth: 2,
          backgroundColor: ds.data.map((_, i) => COLOR_PALETTE[i % COLOR_PALETTE.length].bg),
          borderColor: ds.data.map((_, i) => COLOR_PALETTE[i % COLOR_PALETTE.length].border),
        };
      }
      return {
        label: ds.label,
        data: [...ds.data],
        borderWidth: 2,
        backgroundColor: ds.backgroundColor,
        borderColor: ds.borderColor,
      };
    });

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const options: any = {
      responsive: true,
      maintainAspectRatio: false,
      plugins: {
        title: {
          display: !!this.data.title,
          text: this.data.title,
          color: textColor,
          font: { size: 16, weight: "600" as const },
        },
        legend: {
          labels: { color: legendColor },
        },
      },
    };

    // Add scales for axis-based chart types
    if (this.data.chartType === "radar") {
      options.scales = {
        r: {
          ticks: { color: textColor, backdropColor: "transparent" },
          grid: { color: gridColor },
          pointLabels: { color: textColor },
        },
      };
    } else if (!isPieType) {
      options.scales = {
        x: {
          ticks: { color: textColor },
          grid: { color: gridColor },
        },
        y: {
          ticks: { color: textColor },
          grid: { color: gridColor },
          beginAtZero: true,
        },
      };
    }

    this.chart = new Chart(this.canvas, {
      type: this.data.chartType,
      data: {
        labels: [...this.data.labels],
        datasets,
      },
      options,
    });
  }

  private scheduleChartUpdate(): void {
    if (this.updateTimeout !== null) {
      clearTimeout(this.updateTimeout);
    }
    this.updateTimeout = window.setTimeout(() => {
      this.updateTimeout = null;
      if (!this.chart) return;

      const isPieType = ["pie", "doughnut", "polarArea"].includes(this.data.chartType);

      this.chart.data.labels = [...this.data.labels];
      this.chart.data.datasets = this.data.datasets.map((ds) => {
        // eslint-disable-next-line @typescript-eslint/no-explicit-any
        const base: any = {
          label: ds.label,
          data: [...ds.data],
          borderWidth: 2,
        };

        if (isPieType) {
          base.backgroundColor = ds.data.map((_, i) => COLOR_PALETTE[i % COLOR_PALETTE.length].bg);
          base.borderColor = ds.data.map((_, i) => COLOR_PALETTE[i % COLOR_PALETTE.length].border);
        } else {
          base.backgroundColor = ds.backgroundColor;
          base.borderColor = ds.borderColor;
        }

        return base;
      });

      // Update title
      if (this.chart.options.plugins?.title) {
        this.chart.options.plugins.title.display = !!this.data.title;
        this.chart.options.plugins.title.text = this.data.title;
      }

      this.chart.update();
    }, 150);
  }

  // ─── Data Management ────────────────────────────────────────────────────────

  private addLabel(): void {
    const idx = this.data.labels.length + 1;
    this.data.labels.push(`Label ${idx}`);
    this.data.datasets.forEach((ds) => ds.data.push(0));
    this.rebuildDataTable();
    this.scheduleChartUpdate();
  }

  private removeLabel(index: number): void {
    if (this.data.labels.length <= 1) return;
    this.data.labels.splice(index, 1);
    this.data.datasets.forEach((ds) => ds.data.splice(index, 1));
    this.rebuildDataTable();
    this.scheduleChartUpdate();
  }

  private addDataset(): void {
    const idx = this.data.datasets.length;
    const color = COLOR_PALETTE[idx % COLOR_PALETTE.length];
    this.data.datasets.push({
      label: `Dataset ${idx + 1}`,
      data: this.data.labels.map(() => 0),
      backgroundColor: color.bg,
      borderColor: color.border,
    });
    this.rebuildDataTable();
    this.scheduleChartUpdate();
  }

  private removeDataset(index: number): void {
    if (this.data.datasets.length <= 1) return;
    this.data.datasets.splice(index, 1);
    this.rebuildDataTable();
    this.scheduleChartUpdate();
  }

  // ─── Helpers ────────────────────────────────────────────────────────────────

  private updateTypeSelector(): void {
    if (!this.wrapper) return;
    const buttons = this.wrapper.querySelectorAll<HTMLButtonElement>(".cdx-chart-block__type-btn");
    buttons.forEach((btn) => {
      btn.classList.toggle(
        "cdx-chart-block__type-btn--active",
        btn.dataset.chartType === this.data.chartType,
      );
    });
  }

  private normalizeData(data: Partial<ChartBlockData>): ChartBlockData {
    const chartType =
      data.chartType &&
      ["bar", "line", "pie", "doughnut", "radar", "polarArea"].includes(data.chartType)
        ? data.chartType
        : DEFAULT_DATA.chartType;

    const title = data.title ?? DEFAULT_DATA.title;
    const labels =
      Array.isArray(data.labels) && data.labels.length > 0 ? data.labels : [...DEFAULT_DATA.labels];

    const datasets =
      Array.isArray(data.datasets) && data.datasets.length > 0
        ? data.datasets.map((ds, idx) => {
            const color = COLOR_PALETTE[idx % COLOR_PALETTE.length];
            return {
              label: ds.label || `Dataset ${idx + 1}`,
              data: Array.isArray(ds.data)
                ? labels.map((_, i) => ds.data[i] ?? 0)
                : labels.map(() => 0),
              backgroundColor: ds.backgroundColor || color.bg,
              borderColor: ds.borderColor || color.border,
            };
          })
        : DEFAULT_DATA.datasets.map((ds) => ({
            ...ds,
            data: labels.map((_, i) => ds.data[i] ?? 0),
          }));

    return { chartType, title, labels, datasets };
  }

  private isDarkMode(): boolean {
    let el: HTMLElement | null = this.wrapper;
    while (el) {
      if (el.getAttribute("data-theme") === "dark") return true;
      el = el.parentElement;
    }
    return false;
  }

  private hexToRgba(hex: string, alpha: number): string {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    return `rgba(${r}, ${g}, ${b}, ${alpha})`;
  }

  private rgbaToHex(rgba: string): string {
    const match = rgba.match(/(\d+),\s*(\d+),\s*(\d+)/);
    if (!match) return "#000000";
    const r = parseInt(match[1]).toString(16).padStart(2, "0");
    const g = parseInt(match[2]).toString(16).padStart(2, "0");
    const b = parseInt(match[3]).toString(16).padStart(2, "0");
    return `#${r}${g}${b}`;
  }
}

"use client";

import { lazy, Suspense, useEffect, useState } from "react";
import type { OutputData } from "@editorjs/editorjs";

/**
 * Client-only, lazily-loaded wrapper around the EditorJS `TextEditor`.
 *
 * EditorJS references DOM globals (`Element`) at module-load time, which crashes
 * server-side rendering. Statically importing `TextEditor` in the field registry
 * would pull it into the SSR bundle; loading it lazily + only after mount keeps
 * the builder SSR-safe — the editor is imported on the client, on demand.
 */
const TextEditorLazy = lazy(() => import("./TextEditor").then((m) => ({ default: m.TextEditor })));

export interface RichTextFieldProps {
  data?: OutputData;
  onChange?: (data: OutputData) => void;
  readOnly?: boolean;
  placeholder?: string;
  /** Editor size — controls min-height + padding (the toolbar gutter). Default "M". */
  size?: "S" | "M" | "L" | "XL";
}

const placeholderBox = (
  <div className="min-h-[200px] w-full rounded-[6px] border border-border-presentation-action-primary bg-background-presentation-form-field-primary" />
);

export function RichTextField({ size = "M", ...props }: RichTextFieldProps) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  if (!mounted) return placeholderBox;

  return (
    <Suspense fallback={placeholderBox}>
      <TextEditorLazy
        size={size}
        className="border border-border-presentation-action-primary"
        {...props}
      />
    </Suspense>
  );
}

RichTextField.displayName = "RichTextField";

/**
 * TableDnDWrapper
 *
 * Wraps @editorjs/table and adds drag-and-drop reordering for rows
 * and columns by hijacking the existing .tc-toolbox toggler elements.
 *
 * - Click the toggler → opens the original popover menu (unchanged)
 * - Drag the toggler → reorders the row/column (new behavior)
 *
 * No extra UI elements are injected — we reuse what the table plugin
 * already renders.
 */

// eslint-disable-next-line @typescript-eslint/no-explicit-any
type TableClass = any;

const DRAG_THRESHOLD = 5; // px before a pointerdown becomes a drag

interface DragState {
  active: boolean;
  pending: boolean; // pointerdown happened but haven't passed threshold
  type: "row" | "col" | null;
  index: number;
  dropIndex: number;
  pointerId: number;
  startX: number;
  startY: number;
}

export default function createTableDnDClass(OriginalTable: TableClass): TableClass {
  return class TableDnD extends OriginalTable {
    private _drag: DragState = {
      active: false,
      pending: false,
      type: null,
      index: -1,
      dropIndex: -1,
      pointerId: -1,
      startX: 0,
      startY: 0,
    };

    private _indicator: HTMLDivElement | null = null;
    private _wrapperRef: HTMLElement | null = null;
    private _onMoveBound = this._onPointerMove.bind(this);
    private _onUpBound = this._onPointerUp.bind(this);
    private _mutationObs: MutationObserver | null = null;
    private _rafId: number | null = null;
    private _attachedTogglers = new WeakSet<HTMLElement>();

    // ─── Lifecycle ──────────────────────────────────────────────────────

    render(): HTMLElement {
      const wrapper: HTMLElement = super.render();
      this._wrapperRef = wrapper;

      if (this.readOnly) return wrapper;

      this._waitForLayout(wrapper, () => this._setup(wrapper));
      return wrapper;
    }

    destroy(): void {
      this._teardown();
      if (super.destroy) super.destroy();
    }

    // ─── Wait for DOM ───────────────────────────────────────────────────

    private _waitForLayout(el: HTMLElement, cb: () => void): void {
      const check = () => {
        if (el.offsetHeight > 0 && el.querySelector(".tc-row")) {
          cb();
        } else {
          this._rafId = requestAnimationFrame(check);
        }
      };
      this._rafId = requestAnimationFrame(check);
    }

    // ─── Setup ──────────────────────────────────────────────────────────

    private _setup(wrapper: HTMLElement): void {
      wrapper.classList.add("tc-dnd-wrap");

      // Drop indicator
      this._indicator = document.createElement("div");
      this._indicator.className = "tc-dnd__indicator";
      wrapper.appendChild(this._indicator);

      // Attach to existing togglers
      this._attachTogglers(wrapper);

      // Re-attach when DOM changes (new rows/cols might create new togglers)
      this._mutationObs = new MutationObserver(() => {
        this._attachTogglers(wrapper);
      });
      this._mutationObs.observe(wrapper, { childList: true, subtree: true });

      // Proximity-based toolbox visibility:
      // Only show row handle near left edge, column handle near top edge
      wrapper.addEventListener("mousemove", (e) => this._onWrapperMouseMove(e));
      wrapper.addEventListener("mouseleave", () => {
        wrapper.classList.remove("tc-dnd--show-row", "tc-dnd--show-col");
      });
    }

    // ─── Attach to .tc-toolbox__toggler elements ────────────────────────

    private _attachTogglers(wrapper: HTMLElement): void {
      // Row toolbox toggler
      const rowToolbox = wrapper.querySelector<HTMLElement>(
        ".tc-toolbox--row .tc-toolbox__toggler",
      );
      if (rowToolbox && !this._attachedTogglers.has(rowToolbox)) {
        this._attachedTogglers.add(rowToolbox);
        rowToolbox.style.cursor = "grab";
        rowToolbox.addEventListener("pointerdown", (e) => {
          this._onTogglerDown("row", wrapper, e);
        });
      }

      // Column toolbox toggler
      const colToolbox = wrapper.querySelector<HTMLElement>(
        ".tc-toolbox--column .tc-toolbox__toggler",
      );
      if (colToolbox && !this._attachedTogglers.has(colToolbox)) {
        this._attachedTogglers.add(colToolbox);
        colToolbox.style.cursor = "grab";
        colToolbox.addEventListener("pointerdown", (e) => {
          this._onTogglerDown("col", wrapper, e);
        });
      }
    }

    // ─── Proximity-based toolbox visibility ──────────────────────────────

    private _onWrapperMouseMove(e: MouseEvent): void {
      const tableEl = this._wrapperRef?.querySelector<HTMLElement>(".tc-table");
      if (!tableEl || !this._wrapperRef) return;

      const tableRect = tableEl.getBoundingClientRect();
      const distFromLeft = e.clientX - tableRect.left;
      const distFromTop = e.clientY - tableRect.top;

      const LEFT_THRESHOLD = 50;
      const TOP_THRESHOLD = 35;

      const nearLeft = distFromLeft <= LEFT_THRESHOLD && distFromLeft >= -30;
      const nearTop = distFromTop <= TOP_THRESHOLD && distFromTop >= -25;

      if (nearLeft && nearTop) {
        // Corner: pick the proportionally closer edge
        const leftRatio = Math.abs(distFromLeft) / LEFT_THRESHOLD;
        const topRatio = Math.abs(distFromTop) / TOP_THRESHOLD;
        if (leftRatio < topRatio) {
          this._wrapperRef.classList.add("tc-dnd--show-row");
          this._wrapperRef.classList.remove("tc-dnd--show-col");
        } else {
          this._wrapperRef.classList.add("tc-dnd--show-col");
          this._wrapperRef.classList.remove("tc-dnd--show-row");
        }
      } else if (nearLeft) {
        this._wrapperRef.classList.add("tc-dnd--show-row");
        this._wrapperRef.classList.remove("tc-dnd--show-col");
      } else if (nearTop) {
        this._wrapperRef.classList.add("tc-dnd--show-col");
        this._wrapperRef.classList.remove("tc-dnd--show-row");
      } else {
        this._wrapperRef.classList.remove("tc-dnd--show-row", "tc-dnd--show-col");
      }
    }

    // ─── Toggler pointerdown (start pending drag) ───────────────────────

    private _onTogglerDown(type: "row" | "col", wrapper: HTMLElement, e: PointerEvent): void {
      // Detect which row/col is currently hovered by the table plugin
      const index = this._detectHoveredIndex(type, wrapper);
      if (index < 0) return;

      this._drag = {
        active: false,
        pending: true,
        type,
        index,
        dropIndex: index,
        pointerId: e.pointerId,
        startX: e.clientX,
        startY: e.clientY,
      };

      document.addEventListener("pointermove", this._onMoveBound);
      document.addEventListener("pointerup", this._onUpBound);
      document.addEventListener("pointercancel", this._onUpBound);
    }

    // ─── Detect hovered row/col index ───────────────────────────────────

    private _detectHoveredIndex(type: "row" | "col", wrapper: HTMLElement): number {
      const tableEl = wrapper.querySelector<HTMLElement>(".tc-table");
      if (!tableEl) return -1;

      if (type === "row") {
        // The row toolbox is positioned at the hovered row.
        // Find which row by comparing toolbox top to row tops.
        const toolbox = wrapper.querySelector<HTMLElement>(".tc-toolbox--row");
        if (!toolbox) return -1;
        const toolboxRect = toolbox.getBoundingClientRect();
        const toolboxMid = toolboxRect.top + toolboxRect.height / 2;

        const rows = tableEl.querySelectorAll<HTMLElement>(".tc-row");
        for (let i = 0; i < rows.length; i++) {
          const r = rows[i].getBoundingClientRect();
          if (toolboxMid >= r.top && toolboxMid <= r.bottom) return i;
        }
        return -1;
      } else {
        const toolbox = wrapper.querySelector<HTMLElement>(".tc-toolbox--column");
        if (!toolbox) return -1;
        const toolboxRect = toolbox.getBoundingClientRect();
        const toolboxMid = toolboxRect.left + toolboxRect.width / 2;

        const firstRow = tableEl.querySelector<HTMLElement>(".tc-row");
        if (!firstRow) return -1;
        const cells = firstRow.querySelectorAll<HTMLElement>(".tc-cell");
        for (let i = 0; i < cells.length; i++) {
          const r = cells[i].getBoundingClientRect();
          if (toolboxMid >= r.left && toolboxMid <= r.right) return i;
        }
        return -1;
      }
    }

    // ─── Pointer Move ───────────────────────────────────────────────────

    private _onPointerMove(e: PointerEvent): void {
      const d = this._drag;
      if (!d.pending && !d.active) return;

      // Check threshold to start drag
      if (d.pending && !d.active) {
        const dx = e.clientX - d.startX;
        const dy = e.clientY - d.startY;
        if (Math.abs(dx) + Math.abs(dy) < DRAG_THRESHOLD) return;

        // Passed threshold → start real drag
        d.pending = false;
        d.active = true;

        // Close any open popover from the table plugin
        const openPopover = this._wrapperRef?.querySelector<HTMLElement>(".tc-popover--opened");
        openPopover?.classList.remove("tc-popover--opened");

        this._highlight(d.type!, d.index, true);
        document.body.style.cursor = "grabbing";
        document.body.style.userSelect = "none";
      }

      if (!d.active || !this._wrapperRef) return;
      e.preventDefault();

      const drop = this._calcDrop(this._wrapperRef, e.clientX, e.clientY);
      if (drop !== d.dropIndex) {
        d.dropIndex = drop;
        this._showIndicator(this._wrapperRef, drop);
      }
    }

    // ─── Pointer Up ─────────────────────────────────────────────────────

    private _onPointerUp(e: PointerEvent): void {
      const d = this._drag;
      const wasDragging = d.active;

      if (wasDragging) {
        e.preventDefault();
        e.stopPropagation();

        this._highlight(d.type!, d.index, false);
        if (this._indicator) this._indicator.style.display = "none";

        document.body.style.cursor = "";
        document.body.style.userSelect = "";

        if (d.dropIndex !== d.index && d.dropIndex !== -1) {
          if (d.type === "row") this._moveRow(d.index, d.dropIndex);
          else this._moveCol(d.index, d.dropIndex);
        }

        // Swallow the click event that the browser fires after pointerup
        // so the popover menu doesn't open after a drag.
        const swallowClick = (ev: Event) => {
          ev.preventDefault();
          ev.stopPropagation();
          ev.stopImmediatePropagation();
        };
        document.addEventListener("click", swallowClick, {
          capture: true,
          once: true,
        });
        // Safety: remove after a short delay in case click never fires
        setTimeout(() => {
          document.removeEventListener("click", swallowClick, {
            capture: true,
          });
        }, 200);
      }

      // If pending (no drag threshold met) — let the click go through
      // to the original popover menu handler.

      // Reset
      d.active = false;
      d.pending = false;
      document.removeEventListener("pointermove", this._onMoveBound);
      document.removeEventListener("pointerup", this._onUpBound);
      document.removeEventListener("pointercancel", this._onUpBound);
    }

    // ─── Move Row / Column ──────────────────────────────────────────────

    private _moveRow(from: number, to: number): void {
      const tableEl = this._wrapperRef?.querySelector<HTMLElement>(".tc-table");
      if (!tableEl) return;

      const rows = Array.from(tableEl.querySelectorAll<HTMLElement>(".tc-row"));
      if (from < 0 || from >= rows.length) return;

      const target = to > from ? to - 1 : to;
      if (target === from) return;

      const row = rows[from];
      const ref = rows[target];
      if (target > from) {
        ref.parentElement!.insertBefore(row, ref.nextSibling);
      } else {
        ref.parentElement!.insertBefore(row, ref);
      }
    }

    private _moveCol(from: number, to: number): void {
      const tableEl = this._wrapperRef?.querySelector<HTMLElement>(".tc-table");
      if (!tableEl) return;

      const target = to > from ? to - 1 : to;
      if (target === from) return;

      tableEl.querySelectorAll<HTMLElement>(".tc-row").forEach((row) => {
        const cells = Array.from(row.querySelectorAll<HTMLElement>(".tc-cell"));
        if (from >= cells.length) return;

        const cell = cells[from];
        const ref = cells[target];
        if (target > from) {
          row.insertBefore(cell, ref.nextSibling);
        } else {
          row.insertBefore(cell, ref);
        }
      });
    }

    // ─── Drop Index Calc ────────────────────────────────────────────────

    private _calcDrop(wrapper: HTMLElement, cx: number, cy: number): number {
      const tableEl = wrapper.querySelector<HTMLElement>(".tc-table");
      if (!tableEl) return this._drag.index;

      if (this._drag.type === "row") {
        const rows = tableEl.querySelectorAll<HTMLElement>(".tc-row");
        for (let i = 0; i < rows.length; i++) {
          const r = rows[i].getBoundingClientRect();
          if (cy < r.top + r.height / 2) return i;
        }
        return rows.length;
      } else {
        const first = tableEl.querySelector<HTMLElement>(".tc-row");
        if (!first) return this._drag.index;
        const cells = first.querySelectorAll<HTMLElement>(".tc-cell");
        for (let i = 0; i < cells.length; i++) {
          const r = cells[i].getBoundingClientRect();
          if (cx < r.left + r.width / 2) return i;
        }
        return cells.length;
      }
    }

    // ─── Visual Feedback ────────────────────────────────────────────────

    private _highlight(type: "row" | "col", idx: number, on: boolean): void {
      const tableEl = this._wrapperRef?.querySelector<HTMLElement>(".tc-table");
      if (!tableEl) return;

      if (type === "row") {
        const rows = tableEl.querySelectorAll<HTMLElement>(".tc-row");
        rows[idx]?.classList.toggle("tc-dnd__row--dragging", on);
      } else {
        tableEl.querySelectorAll<HTMLElement>(".tc-row").forEach((row) => {
          const cells = row.querySelectorAll<HTMLElement>(".tc-cell");
          cells[idx]?.classList.toggle("tc-dnd__cell--dragging", on);
        });
      }
    }

    private _showIndicator(wrapper: HTMLElement, dropIdx: number): void {
      if (!this._indicator) return;
      const tableEl = wrapper.querySelector<HTMLElement>(".tc-table");
      if (!tableEl) return;

      const { type, index } = this._drag;
      if (dropIdx === index || dropIdx === index + 1) {
        this._indicator.style.display = "none";
        return;
      }

      const wrapRect = wrapper.getBoundingClientRect();
      this._indicator.style.display = "block";

      if (type === "row") {
        const rows = tableEl.querySelectorAll<HTMLElement>(".tc-row");
        const tableRect = tableEl.getBoundingClientRect();
        let y: number;
        if (dropIdx >= rows.length) {
          y = rows[rows.length - 1].getBoundingClientRect().bottom;
        } else {
          y = rows[dropIdx].getBoundingClientRect().top;
        }
        this._indicator.style.left = `${tableRect.left - wrapRect.left}px`;
        this._indicator.style.top = `${y - wrapRect.top - 2}px`;
        this._indicator.style.width = `${tableRect.width}px`;
        this._indicator.style.height = "4px";
      } else {
        const first = tableEl.querySelector<HTMLElement>(".tc-row");
        if (!first) return;
        const cells = first.querySelectorAll<HTMLElement>(".tc-cell");
        const tableRect = tableEl.getBoundingClientRect();
        let x: number;
        if (dropIdx >= cells.length) {
          x = cells[cells.length - 1].getBoundingClientRect().right;
        } else {
          x = cells[dropIdx].getBoundingClientRect().left;
        }
        this._indicator.style.left = `${x - wrapRect.left - 2}px`;
        this._indicator.style.top = `${tableRect.top - wrapRect.top}px`;
        this._indicator.style.width = "4px";
        this._indicator.style.height = `${tableRect.height}px`;
      }
    }

    // ─── Cleanup ────────────────────────────────────────────────────────

    private _teardown(): void {
      if (this._rafId) cancelAnimationFrame(this._rafId);
      document.removeEventListener("pointermove", this._onMoveBound);
      document.removeEventListener("pointerup", this._onUpBound);
      document.removeEventListener("pointercancel", this._onUpBound);
      this._mutationObs?.disconnect();
      this._indicator?.remove();
      document.body.style.cursor = "";
      document.body.style.userSelect = "";
    }
  };
}

